import{_ as e,r as s,o,c as l,e as n,a as c,s as r}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"导入导出控制器 - October CMS - 3.x","titleTemplate":false,"description":"为页面添加导入和导出功能。","frontmatter":{"subtitle":"为页面添加导入和导出功能。"},"headers":[{"level":2,"title":"配置行为","slug":"配置行为","link":"#配置行为","children":[{"level":3,"title":"导入页面","slug":"导入页面","link":"#导入页面","children":[]},{"level":3,"title":"导出页面","slug":"导出页面","link":"#导出页面","children":[]},{"level":3,"title":"格式选项","slug":"格式选项","link":"#格式选项","children":[]}]},{"level":2,"title":"导入和导出视图","slug":"导入和导出视图","link":"#导入和导出视图","children":[{"level":3,"title":"导入视图","slug":"导入视图","link":"#导入视图","children":[]},{"level":3,"title":"导出视图","slug":"导出视图","link":"#导出视图","children":[]}]},{"level":2,"title":"与列表行为集成","slug":"与列表行为集成","link":"#与列表行为集成","children":[]}],"relativePath":"3.x/zh-cn/extend/importexport/importexport-controller.md","filePath":"3.x/zh-cn/extend/importexport/importexport-controller.md"}'),u={name:"3.x/zh-cn/extend/importexport/importexport-controller.md"};function i(d,a,k,g,m,h){const t=s("pre-heading"),p=s("post-heading");return o(),l("div",null,[n(t),a[0]||(a[0]=c("h1",null,"导入导出控制器",-1)),n(p),a[1]||(a[1]=r(`<p><code>Backend\\Behaviors\\ImportExportController</code> 类是一个控制器行为，提供导入和导出数据的功能。该行为提供两个页面：导入和导出。导入页面允许用户上传 CSV 文件并将列匹配到数据库。导出页面则相反，允许用户将数据库中的列下载为 CSV 文件。该行为提供控制器操作 <code>import()</code> 和 <code>export()</code>。</p><p>导入和导出行为配置分为两部分定义，每部分依赖于一个特殊的模型类以及列表和表单字段定义文件。要使用此行为，您应该将其添加到控制器类的 <code>$implement</code> 属性中。同时，应定义 <code>$importExportConfig</code> 类属性，其值应引用用于配置行为属性的 YAML 文件。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">namespace</span> <span class="token package">Acme<span class="token punctuation">\\</span>Shop<span class="token punctuation">\\</span>Controllers</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">Products</span> <span class="token keyword">extends</span> <span class="token class-name">Controller</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$implement</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Backend<span class="token punctuation">\\</span>Behaviors<span class="token punctuation">\\</span>ImportExportController</span><span class="token operator">::</span><span class="token keyword">class</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token variable">$importExportConfig</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;config_import_export.yaml&#39;</span><span class="token punctuation">;</span>

    <span class="token comment">// [...]</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="配置行为"><a href="#配置行为" class="header-anchor">#</a> 配置行为</h2><p>在 <code>$importExportConfig</code> 属性中引用的配置文件以 YAML 格式定义。该文件应放置在控制器的<a href="./../system/views.html">视图目录</a>中。以下是一个配置文件示例。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token comment"># config_import_export.yaml</span>
<span class="token key atrule">import</span><span class="token punctuation">:</span>
    <span class="token key atrule">title</span><span class="token punctuation">:</span> Import Subscribers
    <span class="token key atrule">modelClass</span><span class="token punctuation">:</span> Acme\\Campaign\\Models\\SubscriberImport
    <span class="token key atrule">list</span><span class="token punctuation">:</span> $/acme/campaign/models/subscriber/columns.yaml

<span class="token key atrule">export</span><span class="token punctuation">:</span>
    <span class="token key atrule">title</span><span class="token punctuation">:</span> Export Subscribers
    <span class="token key atrule">modelClass</span><span class="token punctuation">:</span> Acme\\Campaign\\Models\\SubscriberExport
    <span class="token key atrule">list</span><span class="token punctuation">:</span> $/acme/campaign/models/subscriber/columns.yaml
</code></pre></div><p>以下列出的配置属性是可选的。如果希望行为支持导入页面或导出页面（或两者），请定义这些属性。</p><div class="table"><table tabindex="0"><thead><tr><th>属性</th><th>描述</th></tr></thead><tbody><tr><td><strong>defaultRedirect</strong></td><td>未定义特定重定向页面时用作后备的重定向页面。</td></tr><tr><td><strong>import</strong></td><td>导入页面的配置数组或配置文件引用。</td></tr><tr><td><strong>export</strong></td><td>导出页面的配置数组或配置文件引用。</td></tr><tr><td><strong>defaultFormatOptions</strong></td><td>默认 CSV 格式选项的配置数组或配置文件引用。</td></tr></tbody></table></div><h3 id="导入页面"><a href="#导入页面" class="header-anchor">#</a> 导入页面</h3><p>要支持导入页面，请在 YAML 文件中添加以下配置。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">import</span><span class="token punctuation">:</span>
    <span class="token key atrule">title</span><span class="token punctuation">:</span> Import Subscribers
    <span class="token key atrule">modelClass</span><span class="token punctuation">:</span> Acme\\Campaign\\Models\\SubscriberImport
    <span class="token key atrule">list</span><span class="token punctuation">:</span> $/acme/campaign/models/subscriberimport/columns.yaml
    <span class="token key atrule">redirect</span><span class="token punctuation">:</span> acme/campaign/subscribers
</code></pre></div><p>导入页面支持以下配置属性。</p><div class="table"><table tabindex="0"><thead><tr><th>属性</th><th>描述</th></tr></thead><tbody><tr><td><strong>title</strong></td><td>页面标题，可引用<a href="./../system/localization.html">本地化字符串</a>。</td></tr><tr><td><strong>list</strong></td><td>定义可用于导入的列表列。</td></tr><tr><td><strong>form</strong></td><td>提供用作导入选项的额外字段，可选。</td></tr><tr><td><strong>redirect</strong></td><td>导入完成时的重定向页面，可选。</td></tr><tr><td><strong>permissions</strong></td><td>执行操作所需的用户权限，可选。</td></tr></tbody></table></div><h3 id="导出页面"><a href="#导出页面" class="header-anchor">#</a> 导出页面</h3><p>要支持导出页面，请在 YAML 文件中添加以下配置。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">export</span><span class="token punctuation">:</span>
    <span class="token key atrule">title</span><span class="token punctuation">:</span> Export Subscribers
    <span class="token key atrule">modelClass</span><span class="token punctuation">:</span> Acme\\Campaign\\Models\\SubscriberExport
    <span class="token key atrule">list</span><span class="token punctuation">:</span> $/acme/campaign/models/subscriberexport/columns.yaml
    <span class="token key atrule">redirect</span><span class="token punctuation">:</span> acme/campaign/subscribers
</code></pre></div><p>导出页面支持以下配置属性：</p><div class="table"><table tabindex="0"><thead><tr><th>属性</th><th>描述</th></tr></thead><tbody><tr><td><strong>title</strong></td><td>页面标题，可引用<a href="./../system/localization.html">本地化字符串</a>。</td></tr><tr><td><strong>fileName</strong></td><td>导出文件使用的文件名（不含扩展名）。默认值：<code>export</code></td></tr><tr><td><strong>list</strong></td><td>定义可用于导出的列表列。</td></tr><tr><td><strong>form</strong></td><td>提供用作导出选项的额外字段，可选。</td></tr><tr><td><strong>redirect</strong></td><td>导出完成时的重定向页面，可选。</td></tr><tr><td><strong>useList</strong></td><td>设置为 true 或列表定义的值以启用与列表的集成。默认值：<code>false</code>。</td></tr></tbody></table></div><h3 id="格式选项"><a href="#格式选项" class="header-anchor">#</a> 格式选项</h3><p>要覆盖默认格式选项，请在 YAML 文件中添加以下配置：</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">defaultFormatOptions</span><span class="token punctuation">:</span>
    <span class="token key atrule">fileFormat</span><span class="token punctuation">:</span> json
</code></pre></div><p>以下配置属性（全部可选）支持格式选项，包括其适用的格式类型。</p><div class="table"><table tabindex="0"><thead><tr><th>属性</th><th>描述</th><th>格式</th></tr></thead><tbody><tr><td><strong>fileFormat</strong></td><td>文件格式，可选 <code>json</code>、<code>csv</code> 或 <code>csv_custom</code>，默认值：<code>json</code>。</td><td></td></tr><tr><td><strong>customJson</strong></td><td>为 <code>json</code> 格式类型使用自定义格式。</td><td>JSON</td></tr><tr><td><strong>firstRowTitles</strong></td><td>第一行包含标题，仅导入。</td><td>CSV</td></tr><tr><td><strong>delimiter</strong></td><td>分隔符字符。</td><td>CSV（自定义）</td></tr><tr><td><strong>enclosure</strong></td><td>包围符字符。</td><td>CSV（自定义）</td></tr><tr><td><strong>escape</strong></td><td>转义字符。</td><td>CSV（自定义）</td></tr><tr><td><strong>encoding</strong></td><td>文件编码，仅导入。</td><td>CSV（自定义）</td></tr></tbody></table></div><h2 id="导入和导出视图"><a href="#导入和导出视图" class="header-anchor">#</a> 导入和导出视图</h2><p>对于导入和导出页面功能，您应该提供具有对应名称的<a href="./../system/views.html">视图文件</a>——<strong>import.htm</strong> 和 <strong>export.htm</strong>。</p><p>导入/导出行为向控制器类添加两个方法：<code>importRender</code> 和 <code>exportRender</code>。这些方法按照上述 YAML 配置文件渲染导入和导出部分。</p><h3 id="导入视图"><a href="#导入视图" class="header-anchor">#</a> 导入视图</h3><p><strong>import.htm</strong> 视图代表允许用户导入数据的导入页面。典型的导入页面包含面包屑导航、导入部分本身和提交按钮。<strong>data-request</strong> 属性应引用行为提供的 <code>onImport</code> AJAX 处理程序。以下是典型 import.htm 视图文件的内容。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token class-name static-context">Form</span><span class="token operator">::</span><span class="token function">open</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;class&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;layout&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>

    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>layout-row<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
        <span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">importRender</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>

    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>form-buttons<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span>
            <span class="token attr-name">type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>submit<span class="token punctuation">&quot;</span></span>
            <span class="token attr-name">data-control</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>popup<span class="token punctuation">&quot;</span></span>
            <span class="token attr-name">data-handler</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onImportLoadForm<span class="token punctuation">&quot;</span></span>
            <span class="token attr-name">data-keyboard</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>false<span class="token punctuation">&quot;</span></span>
            <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>btn btn-primary<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
            Import records
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>

<span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token class-name static-context">Form</span><span class="token operator">::</span><span class="token function">close</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
</code></pre></div><h3 id="导出视图"><a href="#导出视图" class="header-anchor">#</a> 导出视图</h3><p><strong>export.htm</strong> 视图代表允许用户从数据库导出文件的导出页面。典型的导出页面包含面包屑导航、导出部分本身和提交按钮。<strong>data-request</strong> 属性应引用行为提供的 <code>onExport</code> AJAX 处理程序。以下是典型 export.htm 表单的内容。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token class-name static-context">Form</span><span class="token operator">::</span><span class="token function">open</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;class&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;layout&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>

    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>layout-row<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
        <span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">exportRender</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>

    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>form-buttons<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span>
            <span class="token attr-name">type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>submit<span class="token punctuation">&quot;</span></span>
            <span class="token attr-name">data-control</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>popup<span class="token punctuation">&quot;</span></span>
            <span class="token attr-name">data-handler</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onExportLoadForm<span class="token punctuation">&quot;</span></span>
            <span class="token attr-name">data-keyboard</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>false<span class="token punctuation">&quot;</span></span>
            <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>btn btn-primary<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
            Export records
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>

<span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token class-name static-context">Form</span><span class="token operator">::</span><span class="token function">close</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
</code></pre></div><h2 id="与列表行为集成"><a href="#与列表行为集成" class="header-anchor">#</a> 与列表行为集成</h2><p>还有一种替代的导出数据方法，使用<a href="./../lists/list-controller.html">列表行为</a>来提供导出数据。要使用此功能，您应该在控制器类的 <code>$implement</code> 字段中添加 <code>Backend\\Behaviors\\ListController</code> 定义。您不需要使用导出视图，所有设置将从列表中获取。以下是唯一需要的配置：</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">export</span><span class="token punctuation">:</span>
    <span class="token key atrule">useList</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>
</code></pre></div><p>然后只需在<a href="./../lists/list-controller.html">列表工具栏</a>中添加一个导出按钮：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>a</span>
    <span class="token attr-name">href</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token class-name static-context">Backend</span><span class="token operator">::</span><span class="token function">url</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme/campaign/subscribers/export&#39;</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span><span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>btn btn-default oc-icon-download<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    Export Records
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>a</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>同样，要添加导入按钮，代码如下所示：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>a</span>
    <span class="token attr-name">href</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token class-name static-context">Backend</span><span class="token operator">::</span><span class="token function">url</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme/campaign/subscribers/import&#39;</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span><span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>btn btn-default oc-icon-upload<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    Import Records
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>a</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>如果您使用<a href="./../lists/list-controller.html">多个列表定义</a>，则可以提供列表定义。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">export</span><span class="token punctuation">:</span>
    <span class="token key atrule">useList</span><span class="token punctuation">:</span> orders
    <span class="token key atrule">fileName</span><span class="token punctuation">:</span> orders.csv
</code></pre></div><p><code>useList</code> 选项还支持扩展配置属性。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">export</span><span class="token punctuation">:</span>
    <span class="token key atrule">useList</span><span class="token punctuation">:</span>
        <span class="token key atrule">definition</span><span class="token punctuation">:</span> orders
        <span class="token key atrule">raw</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>
</code></pre></div><p>支持以下配置属性：</p><div class="table"><table tabindex="0"><thead><tr><th>属性</th><th>描述</th></tr></thead><tbody><tr><td><strong>definition</strong></td><td>用于获取记录的列表定义，可选。</td></tr><tr><td><strong>raw</strong></td><td>从记录输出原始属性值，默认值：false。</td></tr></tbody></table></div>`,45))])}const y=e(u,[["render",i]]);export{v as __pageData,y as default};
